import sys

def is_subsequence(s, t):
    it = iter(t)
    return all(c in it for c in s)

def is_regular_bracket_sequence(s):
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def merge_sequences(s, t):
    dp = [[0] * (len(t) + 1) for _ in range(len(s) + 1)]
    for i in range(len(s)):
        for j in range(len(t)):
            if s[i] == t[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    i, j = len(s), len(t)
    merged = []
    while i > 0 or j > 0:
        if i > 0 and j > 0 and s[i - 1] == t[j - 1]:
            merged.append(s[i - 1])
            i -= 1
            j -= 1
        elif i > 0 and (j == 0 or dp[i][j - 1] <= dp[i - 1][j]):
            merged.append(s[i - 1])
            i -= 1
        else:
            merged.append(t[j - 1])
            j -= 1

    merged.reverse()
    balance = 0
    result = []
    for c in merged:
        result.append(c)
        if c == '(':
            balance += 1
        else:
           balance -= 1
        while balance < 0:
            result.append('(')
            balance += 1
    result.extend([')'] * balance)
    return ''.join(result)

s, t = sys.stdin.read().splitlines()
result = merge_sequences(s, t)
print(result)
